package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Costs.List(
		context.TODO(),
		openai.AdminOrganizationCostListParams{
			StartTime: 1,
			EndTime: param.NewOpt[int64](1),
			BucketWidth: param.NewOpt[string]("1d"),
			ProjectIds: []string{"string"},
			APIKeyIds: []string{"string"},
			GroupBy: []openai.AdminOrganizationCostsListGroupByItem{openai.AdminOrganizationCostsListGroupByItemProjectID},
			Limit: param.NewOpt[int64](7),
			Page: param.NewOpt[string]("page"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
